<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { createSyncClient } from '../../js/core/sync-client.js';

const router = useRouter();
const sync = createSyncClient();
const state = ref<any>({ authenticated:false, online:navigator.onLine, apiUrl:'/api', user:null, lastError:'', conflict:null });
const form = ref({ email:'', password:'', name:'' });
const mode = ref<'login'|'register'>('login');
const busy = ref(false); const message = ref(''); const cases = ref<any[]>([]);
function client(){ return sync; }
function refresh(){ state.value = { ...state.value, ...(client()?.getState?.() || {}), online:navigator.onLine }; }
async function submit(){ busy.value=true;message.value='';try{ if(mode.value==='login') await client().login(form.value.email,form.value.password); else await client().register(form.value.email,form.value.password,form.value.name); message.value='Sesión iniciada correctamente.'; await loadCases(); }catch(e:any){message.value=e?.message||'No se pudo completar la operación.';}finally{busy.value=false;refresh();}}
async function loadCases(){try{cases.value=await client().listCases();}catch(e:any){message.value=e?.message||'No se pudieron cargar los casos.';}}
async function syncNow(){busy.value=true;message.value='';try{const result=await client().syncNow();message.value=result?.ok?'Sincronización completada.':(result?.error||'Sincronización pendiente.');await loadCases();}catch(e:any){message.value=e?.message||'Error de sincronización.';}finally{busy.value=false;refresh();}}
async function resolve(strategy:'server'|'client'){busy.value=true;try{const result=await client().resolveConflict(strategy);message.value=result.ok?'Conflicto resuelto.':result.error;refresh();}finally{busy.value=false;}}
function logout(){client().logout();cases.value=[];message.value='Sesión cerrada.';refresh();}
function onState(e:Event){state.value={...state.value,...((e as CustomEvent).detail||{})};}
onMounted(()=>{refresh();window.addEventListener('mindplace:sync-state',onState);if(client()?.getToken?.())void loadCases();});
onBeforeUnmount(()=>{window.removeEventListener('mindplace:sync-state',onState);sync.destroy();});
</script>
<template>
  <main class="phase32">
    <header><div><p class="eyebrow">FASE 32 · 383–394</p><h1>Backend y sincronización multidispositivo</h1><span>API NestJS, autenticación, sincronización optimista y recuperación ante conflictos, manteniendo el modo local-first.</span></div><button @click="router.push('/')">← Tablero</button></header>
    <section class="toolbar"><label>API <input :value="state.apiUrl" readonly aria-label="URL API"></label><span :class="state.online?'ok':'warn'">{{ state.online?'Conectado':'Offline' }}</span><span :class="state.authenticated?'ok':'info'">{{ state.authenticated?'Autenticado':'Sin sesión' }}</span><button v-if="state.authenticated" @click="syncNow" :disabled="busy">Sincronizar ahora</button><button v-if="state.authenticated" @click="logout">Cerrar sesión</button></section>
    <section v-if="!state.authenticated" class="auth"><div class="tabs"><button :class="{active:mode==='login'}" @click="mode='login'">Iniciar sesión</button><button :class="{active:mode==='register'}" @click="mode='register'">Crear cuenta</button></div><input v-if="mode==='register'" v-model="form.name" placeholder="Nombre"><input v-model="form.email" type="email" placeholder="Email"><input v-model="form.password" type="password" placeholder="Contraseña (mínimo 8 caracteres)"><button @click="submit" :disabled="busy || !state.online">{{ mode==='login'?'Entrar':'Crear cuenta' }}</button><p>{{ message }}</p><small>El navegador usa la API del mismo origen. En LAN, abre MindPlace desde la IP del PC servidor.</small></section>
    <section v-else class="grid"><article><b>Usuario</b><strong>{{ state.user?.email }}</strong><small>JWT de sesión · API REST protegida</small></article><article><b>Casos remotos</b><strong>{{ cases.length }}</strong><small>Casos disponibles para este usuario.</small></article><article><b>Conflictos</b><strong>{{ state.conflict ? '1 pendiente' : '0' }}</strong><small>Se conservan ambas versiones antes de resolver.</small></article><article><b>Modo local</b><strong class="ok">Siempre disponible</strong><small>IndexedDB sigue siendo la base de trabajo local.</small></article></section>
    <section v-if="state.conflict" class="conflict"><h2>Conflicto detectado</h2><p>Otro dispositivo modificó el mismo caso después de la versión local. Puedes conservar el servidor o publicar tu versión local.</p><div><button @click="resolve('server')">Conservar servidor</button><button @click="resolve('client')">Conservar mi versión</button></div></section>
    <p v-if="message && state.authenticated" class="message">{{ message }}</p>
    <section class="matrix"><article v-for="item in [['383–388','Backend/API','Servidor Node.js con NestJS, API REST, autenticación JWT y almacenamiento persistente local del servidor.'],['389–390','Multidispositivo','Casos sincronizados por usuario y dispositivo mediante versiones optimistas.'],['391–393','Conflictos','El servidor rechaza versiones base obsoletas y devuelve la versión conflictiva para resolución explícita.'],['394','Local-first','La app sigue trabajando con IndexedDB cuando el servidor está caído o no hay conexión.'] ]" :key="item[0]"><b>{{item[0]}}</b><h2>{{item[1]}}</h2><p>{{item[2]}}</p></article></section>
  </main>
</template>
<style scoped>
.phase32{min-height:100dvh;box-sizing:border-box;padding:22px;color:#e8eef6;background:#0b1120;font:14px/1.45 Inter,system-ui,sans-serif}.phase32 header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.eyebrow{font-size:11px;letter-spacing:.16em;color:#91a2bb;font-weight:800}.phase32 h1{margin:4px 0 7px;font-size:clamp(28px,5vw,46px)}header span,.matrix p,small{color:#93a1b5}.phase32 header button,.toolbar button,.auth button,.tabs button,.conflict button{border:1px solid #33455d;background:#172237;color:#edf3fa;border-radius:10px;padding:10px 13px;font:inherit;cursor:pointer}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:22px}.toolbar label{display:flex;gap:8px;align-items:center;color:#9eabc0}.toolbar input,.auth input{background:#101a2a;border:1px solid #2b3b52;color:#fff;border-radius:9px;padding:10px 12px;min-width:260px}.ok{color:#70d7ab}.warn{color:#f2be68}.info{color:#9fc0eb}.auth,.conflict{margin-top:22px;max-width:620px;display:grid;gap:10px;padding:20px;border:1px solid #25354b;background:#111b2c;border-radius:15px}.tabs{display:flex;gap:8px}.tabs .active{outline:2px solid #7c9bc4}.grid,.matrix{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:22px}.grid article,.matrix article{display:grid;gap:7px;padding:18px;border:1px solid #25354b;background:#111b2c;border-radius:15px}.grid strong{font-size:19px}.conflict h2{margin:0}.conflict p,.message{color:#b7c2d2}.conflict>div{display:flex;gap:8px}.matrix h2{margin:0;font-size:17px}.matrix p{margin:0}@media(max-width:900px){.grid,.matrix{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.phase32{padding:14px 12px 80px}.phase32 header{flex-direction:column}.grid,.matrix{grid-template-columns:1fr}.toolbar input,.auth input{min-width:0;width:100%}.toolbar label{width:100%;align-items:flex-start;flex-direction:column}.conflict>div{flex-direction:column}}
</style>
